css:
.sl-footer-minimal {
    padding-block: 4.5rem;
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-footer-minimal .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-minimal .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-minimal.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-minimal.sl-border,
.sl-footer-minimal .pt-4.sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-minimal .sl-tracking-widest { letter-spacing: 0.15em; }
.sl-footer-minimal .sl-footer-nav-link,
.sl-footer-minimal .sl-footer-link {
    transition: color 0.2s ease;
}
.sl-footer-minimal .sl-footer-nav-link:hover,
.sl-footer-minimal .sl-footer-nav-link:focus-visible,
.sl-footer-minimal .sl-footer-link:hover,
.sl-footer-minimal .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-minimal .sl-social-icon {
    min-width: 40px;
    min-height: 40px;
    transition: color 0.2s ease, transform 0.2s ease;
}
.sl-footer-minimal .sl-social-icon:hover,
.sl-footer-minimal .sl-social-icon:focus-visible {
    color: var(--smartlearn-primary) !important;
    transform: translateY(-2px);
}
.sl-footer-minimal a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-minimal .sl-footer-nav-link,
    .sl-footer-minimal .sl-footer-link,
    .sl-footer-minimal .sl-social-icon { transition: none; }
    .sl-footer-minimal .sl-social-icon:hover,
    .sl-footer-minimal .sl-social-icon:focus-visible { transform: none; }
}
